CREATE TABLE IF NOT EXISTS mb_artist_top_recording (artistId VARCHAR(36) NOT NULL, recordingMbid BINARY(16) NOT NULL, listenCount BIGINT NOT NULL, userCount BIGINT NOT NULL, CONSTRAINT pk_mb_artist_top_recording PRIMARY KEY (artistId, recordingMbid), CONSTRAINT fk_mb_artist_top_recording_artistId__id FOREIGN KEY (artistId) REFERENCES mb_artist(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS mb_artist_top_recording_fetch (artistId VARCHAR(36) NOT NULL PRIMARY KEY, fetchedAt BIGINT NOT NULL, CONSTRAINT fk_mb_artist_top_recording_fetch_artistId__id FOREIGN KEY (artistId) REFERENCES mb_artist(id) ON DELETE CASCADE ON UPDATE RESTRICT);
